"""Static evaluation plots and the markdown report, generated by
`src/training/train.py` so every figure is reproducible from a single run
rather than hand-built in a notebook.
"""

from __future__ import annotations

from pathlib import Path

import matplotlib

matplotlib.use("Agg")  # noqa: E402 (backend must be set before pyplot is imported)
import matplotlib.pyplot as plt  # noqa: E402
import numpy as np  # noqa: E402
import pandas as pd  # noqa: E402
from sklearn.base import BaseEstimator  # noqa: E402

PRIMARY = "#2E5EAA"
ACCENT = "#E8734A"
NEUTRAL = "#8A94A6"
GRID_COLOR = "#D8DCE3"

plt.rcParams.update(
    {
        "figure.facecolor": "white",
        "axes.facecolor": "white",
        "axes.edgecolor": NEUTRAL,
        "axes.grid": True,
        "grid.color": GRID_COLOR,
        "grid.linewidth": 0.6,
        "font.size": 11,
        "axes.titlesize": 13,
        "axes.titleweight": "bold",
    }
)


def plot_feature_importance(
    model: BaseEstimator, feature_names: list[str], out_path: str | Path, top_n: int = 20
) -> None:
    if hasattr(model, "feature_importances_"):
        importances = np.asarray(model.feature_importances_)
    elif hasattr(model, "coef_"):
        importances = np.abs(np.asarray(model.coef_)).ravel()
    else:
        return

    order = np.argsort(importances)[::-1][:top_n]
    top_features = np.array(feature_names)[order]
    top_importances = importances[order]

    fig, ax = plt.subplots(figsize=(9, max(4, 0.32 * len(top_features))))
    ax.barh(top_features[::-1], top_importances[::-1], color=PRIMARY)
    ax.set_title(f"Top {len(top_features)} Feature Importances")
    ax.set_xlabel("Importance")
    fig.tight_layout()
    fig.savefig(out_path, dpi=150)
    plt.close(fig)


def plot_residuals(y_true: np.ndarray, y_pred: np.ndarray, out_path: str | Path) -> None:
    residuals = np.asarray(y_true) - np.asarray(y_pred)
    fig, ax = plt.subplots(figsize=(8, 5))
    ax.scatter(y_pred, residuals, alpha=0.25, s=10, color=PRIMARY, edgecolors="none")
    ax.axhline(0, color=ACCENT, linewidth=1.5)
    ax.set_title("Residuals vs. Predicted")
    ax.set_xlabel("Predicted units sold")
    ax.set_ylabel("Residual (actual - predicted)")
    fig.tight_layout()
    fig.savefig(out_path, dpi=150)
    plt.close(fig)


def plot_actual_vs_predicted(y_true: np.ndarray, y_pred: np.ndarray, out_path: str | Path) -> None:
    y_true, y_pred = np.asarray(y_true), np.asarray(y_pred)
    fig, ax = plt.subplots(figsize=(6.5, 6.5))
    ax.scatter(y_true, y_pred, alpha=0.25, s=10, color=PRIMARY, edgecolors="none")
    lims = (0.0, max(y_true.max(), y_pred.max()) * 1.02)
    ax.plot(lims, lims, color=ACCENT, linewidth=1.5, label="Perfect prediction")
    ax.set_xlim(lims)
    ax.set_ylim(lims)
    ax.set_title("Actual vs. Predicted Units Sold")
    ax.set_xlabel("Actual units sold")
    ax.set_ylabel("Predicted units sold")
    ax.legend(frameon=False)
    fig.tight_layout()
    fig.savefig(out_path, dpi=150)
    plt.close(fig)


def plot_model_comparison(results_df: pd.DataFrame, out_path: str | Path) -> None:
    fig, ax = plt.subplots(figsize=(8, 5))
    x = np.arange(len(results_df))
    ax.bar(x, results_df["rmse"], color=[PRIMARY if i else ACCENT for i in range(len(results_df))])
    ax.set_xticks(x)
    ax.set_xticklabels(results_df["model"], rotation=20, ha="right")
    ax.set_title("Model Comparison (Test RMSE, lower is better)")
    ax.set_ylabel("RMSE")
    fig.tight_layout()
    fig.savefig(out_path, dpi=150)
    plt.close(fig)


def write_metrics_report(
    results_df: pd.DataFrame,
    best_model_name: str,
    rationale: str,
    out_path: str | Path,
) -> None:
    out_path = Path(out_path)
    lines = [
        "# Model Evaluation Report",
        "",
        "Generated automatically by `src/training/train.py`. Every number below "
        "comes from an actual run of the pipeline against `data/raw/train.csv`; "
        "none of it is hand-entered.",
        "",
        "## Model comparison (held-out test set, last 8 weeks)",
        "",
        results_df.round(4).to_markdown(index=False),
        "",
        f"## Selected model: `{best_model_name}`",
        "",
        rationale,
        "",
        "## Metric notes",
        "",
        "- **RMSE / MAE / R²**: standard regression metrics on the original "
        "`units_sold` scale (predictions from the log1p-trained model are "
        "inverse-transformed with `expm1` before scoring).",
        "- **WAPE** (weighted absolute percentage error) is the primary "
        "percentage-style metric for this dataset.",
        "- **MAPE** is reported for completeness but is unstable here: "
        "`units_sold` has a minimum of 1, so small absolute errors on "
        "low-volume rows produce triple-digit percentage errors.",
        "",
    ]
    out_path.write_text("\n".join(lines), encoding="utf-8")
